import { Controller, Get, Post, Req, Logger } from '@nestjs/common';
import { Request } from 'express';
import { SubscribeMessageService } from './subscribe.service';

import { EventhubService } from '@/config/eventhub/eventhub.service';

interface SubscribeMetaDataDto {
  pubsubname: string;
  route: string;
  topic: string;
  metadata?: Record<string, string>;
}
const topics = {
  topicTasks: process.env.TOPIC_LEVELING_BOARD_TASKS,
};
@Controller()
export class SubscribeController {
  private readonly logger = new Logger(SubscribeController.name);

  public constructor(
    private readonly subscribeMessageService: SubscribeMessageService,
    private readonly eventhubService: EventhubService,
  ) {}

  @Get('/dapr/subscribe')
  public async subscribeMetaData(): Promise<Array<SubscribeMetaDataDto>> {
    return [
      {
        metadata: {
          checkPointFrequencyPerPartition:
            await this.eventhubService.checkPointFrequencyTasks(),
        },
        pubsubname: this.eventhubService.pubSubName,
        route: `/${this.eventhubService.topicTasks}`,
        topic: this.eventhubService.topicTasks,
      },
    ];
  }

  @Post(`/${topics.topicTasks || 'topic-tasks'}`)
  public async receiveTaskMessage(@Req() request: Request): Promise<string> {
    const { data, partitionKey } = request.body;
    this.logger.log(`partitionKey: ${partitionKey}`);
    await this.subscribeMessageService.handleMessageTask(data);
    return 'OK';
  }
}

