import { JobsLogContext, RedisConnectionService } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { AppLogger } from '@/common/logger/app-logger';
import { MutexManagerService } from '@/common/mutex-manager/mutex-manager.service';
import { appendAndSaveToCacheQueue } from '@/helpers/queues/append-and-save-to-cache-queue';
import { resetQueuesWithLocks } from '@/helpers/queues/reset-queue-with-locks';
import { CacheTask } from '@/interface/cache-task';
import { LauncherKpiMessage } from '@/interface/launcher-kpi-message';
import { QueueMessage } from '@/interface/queue-message';
import { WorkcenterUpdatesMessage } from '@/interface/workcenter-updates-message';
import { LastUpdateTaskRecordService } from '@/update-cache/last-update-task-records.service';
import { WorkersService } from '@/workers/workers.service';

@Injectable()
export class SubscribeMessageService {
  private static checkRedisClient(isClientConnected: boolean): void {
    if (!isClientConnected) {
      throw new Error(
        'Redis client is not connected or connection is closed (handleMessageTask).',
      );
    }
  }

  public constructor(
    private readonly picsinaService: WorkersService,
    private readonly lastUpdateTaskRecordService: LastUpdateTaskRecordService,
    private readonly mutexManagerService: MutexManagerService,
    private readonly customLogger: AppLogger,
    private readonly redisConnection: RedisConnectionService,
  ) {}

  public async handleMessageTask(message: CacheTask): Promise<void> {
    const context: JobsLogContext = {
      method: 'handleMessageTask',
      plant: message.plant,
      service: 'SubscribeMessageService',
    };
    try {
      const redisClient = await this.redisConnection.getClient();
      if (!redisClient?.isOpen || !redisClient?.isReady) {
        this.customLogger.log(
          'Redis client not connected or not ready',
          context,
        );
        throw new Error('Redis client is not connected or ready.');
      }
      if (!redisClient) {
        throw new Error(
          'Redis client is not connected From handleMessageTask .',
        );
      }
      SubscribeMessageService.checkRedisClient(redisClient.isOpen);
      const plant = String(message.plant);
      const lastUpdateRecordResult =
        await this.lastUpdateTaskRecordService.readLastUpdateTaskRecord(plant);

      if (
        message.tpaAssignement !== undefined &&
        message.tpaAssignement !== null
      ) {
        // Add message to Redis queue for TPA assignment
        const queueMessage: QueueMessage = {
          plant: message.plant,
          tpaAssignement: message.tpaAssignement,
        };
        SubscribeMessageService.checkRedisClient(redisClient.isOpen);
        await appendAndSaveToCacheQueue(
          this.customLogger,
          'tpa',
          queueMessage,
          this.mutexManagerService,
          redisClient,
        );
        return;
      }
      if (message.outbound !== undefined && message.outbound !== null) {
        const queueMessage: QueueMessage = {
          outbound: message.outbound,
          plant: message.plant,
        };
        SubscribeMessageService.checkRedisClient(redisClient.isOpen);
        await appendAndSaveToCacheQueue(
          this.customLogger,
          'outbound',
          queueMessage,
          this.mutexManagerService,
          redisClient,
        );
        return;
      }
      if (
        message.workcenterId !== undefined &&
        message.workcenterId !== null &&
        message.kpiName !== 'LAUNCHER_WAITING_TIME'
      ) {
        const queueMessage: WorkcenterUpdatesMessage = {
          workcenterId: message.workcenterId,
          plant: message.plant,
        };
        SubscribeMessageService.checkRedisClient(redisClient.isOpen);
        await appendAndSaveToCacheQueue(
          this.customLogger,
          'workcenter-updates',
          queueMessage,
          this.mutexManagerService,
          redisClient,
        );
        return;
      }

      if (
        message.kpiName !== undefined &&
        message.kpiName === 'LAUNCHER_WAITING_TIME' &&
        message.workcenter !== undefined &&
        message.workcenter !== null
      ) {
        const queueMessage: LauncherKpiMessage = {
          kpiName: message.kpiName,
          plant: message.plant,
          workcenter: message.workcenter,
        };
        SubscribeMessageService.checkRedisClient(redisClient.isOpen);
        await appendAndSaveToCacheQueue(
          this.customLogger,
          'launcher-kpi',
          queueMessage,
          this.mutexManagerService,
          redisClient,
        );

        return;
      }

      if (
        lastUpdateRecordResult &&
        message.updateTime &&
        lastUpdateRecordResult.lastUpdateTime.getTime() ===
          new Date(message.updateTime).getTime()
      ) {
        return;
      }
      lastUpdateRecordResult.lastUpdateTime = message.updateTime;
      await this.lastUpdateTaskRecordService.writeLastUpdateTaskRecord(
        plant,
        lastUpdateRecordResult,
      );
      SubscribeMessageService.checkRedisClient(redisClient.isOpen);
      const messageTask = await resetQueuesWithLocks(
        this.customLogger,
        this.mutexManagerService,
        message,
        message.plant,
        redisClient,
      );
      this.picsinaService.runTask(messageTask);
    } catch (error) {
      this.customLogger.error(
        `Plant ${message.plant} - Error processing message: ${error.message}`,
        context,
        error.stack,
      );
    }
  }
}

