  ): Promise<BufferOrderResponse | undefined> {
    const context: JobsLogContext = {
      method: 'fetchBufferOrdersByDate',
      object: date.toString(),
      plant,
      service: 'OrderApi',
    };

    const serviceAppId = this.daprConfigService.orderApiAppIdInternal;
    const serviceMethodSeqnum = `buffer/getBufferWksByPlant/${plant}/${date.toISOString()}`;
    const url = `${serviceAppId}/${serviceMethodSeqnum}`;

