    plant: number,
    date: string | undefined,
    maxDate: string | undefined = undefined,
  ): Promise<Array<PickingOrderList> | undefined> {
    const context: JobsLogContext = {
      method: 'fetchNotClosedOrdersByDate',
      object: 'materialIds',
      plant,
      service: 'OrderApi',
    };

    try {
      if (date && maxDate) {
        const mindate = new Date(date).toISOString();
        let serviceMethodSeqnum = `picking-order/orders-with-reschudeling-version-triggers/${plant}/${mindate}?notClosed=true`;
        if (maxDate !== undefined) {
          const maxDateString = new Date(maxDate).toISOString();
          serviceMethodSeqnum += `&maxDate=${maxDateString}`;
        }
        const response = await invokeService<Array<PickingOrderList>>(
          {
            context,
            customLogger: this.customLogger,
            daprClient: this.daprClient,
          },
          {
            serviceAppId: this.orderApiAppId,
            serviceMethod: serviceMethodSeqnum,
            method: HttpMethod.GET,
            useAxios: this.useAxios,
          },
        );
        return response;
      }
      return undefined;
    } catch (error) {
      this.customLogger.error(
        `Error in fetchNotClosedOrdersByDate: ${error.message}`,
        context,
        error.stack,
      );
      return undefined;
