  public async fetchOrdersByDateBuffer(
    plant: number,
    date: string | undefined,
  ): Promise<Array<BufferWkResponse> | undefined> {
    const context: JobsLogContext = {
      method: 'fetchOrdersByDateBuffer',
      plant,
      service: 'OrderApi',
    };

    try {
      if (date) {
        const mindate = new Date(date).toISOString();

        const serviceAppId = this.daprConfigService.orderApiAppIdInternal;
        const serviceMethod = `buffer/getBufferWksByPlant/${plant}/${mindate}`;

        const response = await invokeService<Array<BufferWkResponse>>(
          {
            context,
            customLogger: this.customLogger,
            daprClient: this.daprClient,
          },
          {
            serviceAppId,
            serviceMethod,
            method: HttpMethod.GET,
