import { AppLoggerModule } from '@/common/logger/app-logger.module';

@Module({
  exports: [ThreadConfigService],
  imports: [
    ConfigModule.forRoot({
      isGlobal: true,
    }),
    AppConfigModule,
    AppLoggerModule,
  ],
  providers: [ThreadConfigService],
})
export class ThreadConfigModule {}

import { JobsLogContext } from '@mesx/common-lib';
import { Injectable, OnModuleInit } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { AppConfigService } from '../app-config/app-config.service';
import { AppLogger } from '@/common/logger/app-logger';

@Injectable()
export class ThreadConfigService implements OnModuleInit {
  private static readonly maxThreadsDefaultValue = 2;

  public constructor(
    private readonly configService: ConfigService,
    private readonly appConfigService: AppConfigService,
    private readonly customLogger: AppLogger,
  ) {}

  public async maxThreads(): Promise<number> {
    const context: JobsLogContext = {
      method: 'maxThreads',
      service: 'ThreadConfigService',
    };
    let value = this.configService.get<number>('maxThreads');

    if (!value) {
      const valueFromAppConfig =
        await this.appConfigService.getConfigurationValue(
          'LEVELING_BOARD_MV_PROCESSOR_MAX_THREADS',
        );
      value = Number(valueFromAppConfig);
    }
    if (!value) {
      this.customLogger.warn(
        `'maxThreads' is using the default value ${ThreadConfigService.maxThreadsDefaultValue}`,
        context,
      );
    }
    return value ?? ThreadConfigService.maxThreadsDefaultValue;
  }

  public async onModuleInit(): Promise<void> {
    await this.checkConfiguration();
  }

  private async checkConfiguration(): Promise<void> {
    const context: JobsLogContext = {
      method: 'checkConfiguration',
      service: 'ThreadConfigService',
    };
    // List of required configurations
    const requiredConfigs: Array<{
      key: string;
      value: string | number | boolean | undefined;
    }> = [{ key: 'maxThreads', value: await this.maxThreads() }];
    for (const config of requiredConfigs) {
      if (config.value === undefined) {
        this.customLogger.error(
          `Missing configuration value for ${config.key}`,
          context,
        );
        throw new Error(`Configuration error: ${config.key} is not set`);
      }
    }
  }
}

